), sv AS (
  SELECT (SELECT id FROM walk_vertices WHERE in_main ORDER BY geom <-> (SELECT p FROM a) LIMIT 1) AS s,
         (SELECT id FROM walk_vertices WHERE in_main ORDER BY geom <-> (SELECT p FROM b) LIMIT 1) AS t
)
SELECT s, t, (SELECT round(agg_cost::numeric,1) FROM pgr_dijkstra('SELECT id, source, target, cost_m AS cost, cost_m AS reverse_cost FROM walk_edges', s, t, directed => false) WHERE node = t) AS dist_m
FROM sv;

