WITH start AS (
  SELECT v.id FROM walk_vertices v, metro_stations m
  WHERE m.name='新街口' AND v.in_main
  ORDER BY v.geom <-> m.geom LIMIT 1
), dd AS (
  SELECT node FROM pgr_drivingDistance(
    'SELECT id, source, target, cost_m AS cost, cost_m AS reverse_cost FROM walk_edges',
    (SELECT id FROM start), 1200, directed => false)
), reach AS (SELECT node FROM dd UNION SELECT id FROM start),
edges AS (
  SELECT e.geom FROM walk_edges e
  WHERE e.source IN (SELECT node FROM reach) AND e.target IN (SELECT node FROM reach)
), buf AS (
  SELECT ST_Union(ST_Buffer(ST_Simplify(ST_Transform(geom,32650),2),50,'quad_segs=2')) AS g FROM edges
)
SELECT ST_Area(g::geography)/1e6 AS area_km2 FROM buf;

