WITH ra AS (
  SELECT id, name, ST_PointOnSurface(geom) AS pt FROM residential_areas WHERE name = '龙岸花园幸福苑' ORDER BY id LIMIT 1
), sv AS (
  SELECT v.id, v.geom FROM ra, LATERAL (SELECT id, geom FROM walk_vertices WHERE in_main ORDER BY geom <-> ra.pt LIMIT 1) v
), schools AS (
  SELECT p.id, p.name, ST_PointOnSurface(p.geom) AS pt FROM pois p WHERE p.subtype='school' AND p.name LIKE '%小学%'
), sv2 AS (
  SELECT s.id AS school_id, s.name, v.id AS vid FROM schools s, LATERAL (SELECT id FROM walk_vertices WHERE in_main ORDER BY geom <-> s.pt LIMIT 1) v
), dd AS (
  SELECT * FROM pgr_drivingDistance('SELECT id, source, target, cost_m AS cost, cost_m AS reverse_cost FROM walk_edges', (SELECT id FROM sv), 500, directed => false)
)
SELECT (SELECT name FROM ra) AS area, (SELECT count(*) FROM sv2 WHERE vid IN (SELECT node FROM dd)) AS reachable_schools,
       (SELECT min(agg_cost) FROM dd WHERE node IN (SELECT vid FROM sv2)) AS min_cost_m,
       (SELECT string_agg(name, ',') FROM sv2 WHERE vid IN (SELECT node FROM dd)) AS school_names

