WITH ra AS (
  SELECT id, name, ST_PointOnSurface(geom) AS pt FROM residential_areas WHERE name = '大发·燕澜湾西区' ORDER BY id LIMIT 1
), sv AS (
  SELECT v.id, v.geom FROM ra, LATERAL (SELECT id, geom FROM walk_vertices WHERE in_main ORDER BY geom <-> ra.pt LIMIT 1) v
), kg AS (
  SELECT p.id, p.name, ST_PointOnSurface(p.geom) AS pt FROM pois p WHERE p.subtype = 'kindergarten'
), ksnap AS (
  SELECT kg.id, kg.name, (SELECT v.id FROM walk_vertices v WHERE v.in_main ORDER BY v.geom <-> kg.pt LIMIT 1) AS vid FROM kg
), dd AS (
  SELECT * FROM pgr_drivingDistance('SELECT id, source, target, cost_m AS cost, cost_m AS reverse_cost FROM walk_edges', (SELECT id FROM sv), 300, directed => false)
)
SELECT (SELECT id FROM sv) AS start_vertex,
       count(DISTINCT ksnap.id) AS kindergartens_within_300m,
       min(dd.agg_cost) AS nearest_net_m,
       (SELECT name FROM ksnap WHERE vid IN (SELECT node FROM dd) ORDER BY (SELECT min(agg_cost) FROM dd WHERE dd.node = ksnap.vid) LIMIT 1) AS nearest_name
FROM dd JOIN ksnap ON ksnap.vid = dd.node;

